def enrich_product_ddd(source: dict[str, Any]) -> dict[str, Any]:
    dossiers = [_collaboration(), _privacy(), _resolution(), _assurance()]
    truths = {row["product_ref"]: row["product_truth"] for row in dossiers}
    for row in source["artifacts"]:
        truth = truths.get(row.get("artifact_id"))
        if truth:
            row.update({
                "users": truth["users"],
                "harmed_parties": truth["harmed_parties"],
                "jobs": truth["jobs"],
                "outcomes": truth["measurable_outcomes"],
                "automation_modality": AUTOMATION,
            })
    source["ddd_dossiers"] = dossiers
    source["non_collapse_laws"].extend([
        "participant admission != contribution admission != analysis approval != execution success != output release",
        "requestor != data subject != subject scope != record scope != effect target",
        "record occurrence != candidate pair != feature evidence != score != link decision != cluster != master identity",
        "claim != argument != evidence != finding != defeater != appraisal != verdict != relying decision",
    ])
    source["negative_tests"].extend([
        {"test_id": "negative.cpra.collaboration_release_success", "prohibited_claim": "Successful approved computation authorizes output release.", "expected_result": "open a separate scoped output review and authority gate"},
        {"test_id": "negative.cpra.privacy_ack_erasure", "prohibited_claim": "A provider acknowledgement proves verified erasure.", "expected_result": "retain verification pending and exact residual scope"},
        {"test_id": "negative.cpra.resolution_cluster_truth", "prohibited_claim": "A computed entity cluster is authoritative real-world or master identity.", "expected_result": "retain resolution evidence and submit a master proposal"},
        {"test_id": "negative.cpra.assurance_signature_truth", "prohibited_claim": "A valid signature proves appraiser mandate independence or claim truth.", "expected_result": "verify each property separately and preserve bounded verdict limits"},
    ])
    return source

